dense_fused_experiment.source:
package main

import (
 "context"
 "encoding/json"
 "fmt"
 "os"
 "time"
 "github.com/rhawrami/peGosus/pkg/io/parquet"
 "github.com/rhawrami/peGosus/pkg/mem"
 "github.com/rhawrami/peGosus/pkg/peg"
 "github.com/rhawrami/peGosus/pkg/store"
)

func main() {
 const rows = 1048768
 f, err := os.Open("/tmp/peg-baseline.zZwcQ3/bench.parquet"); if err != nil {panic(err)}
 info, err := f.Stat(); if err != nil {panic(err)}
 a := mem.MakeAllocatorWithProfiles([]int{1<<20}, []int{1<<20})
 r, failure := parquet.MakeParquetReaderProjected(f, info.Size(), a, []int{0,5}, parquet.ParquetOptions{}); if failure != nil {panic(failure)}
 var batches []*store.Batch
 var low, high int32
 first := true
 for {
  batch, failure := r.Next(context.Background()); if failure != nil {panic(failure)}; if batch == nil {break}
  ids, days := batch.VectorAt(0).I32s(), batch.VectorAt(1).I32s()
  for i, day := range days {
   for col:=0;col<2;col++ {v:=batch.VectorAt(col); if v.Validity()!=nil && !v.Validity().IsSet(i) {panic("prototype needs all-valid input")}}
   if ids[i]<0 {panic("unexpected negative ID")}
   if first || day<low {low=day}; if first || day>high {high=day}; first=false
  }
  batches=append(batches,batch)
 }
 r.Close(); f.Close()
 table:=store.MakeTable(batches); for _, batch:=range batches {batch.Release()}; defer table.Release()
 engine:=peg.MakeEngine(peg.EngineOptions{MemoryBudget:512<<20,Workers:1})
 prepared,err:=engine.Prepare(engine.ScanTable(table,[]string{"id","day"}).Filter(peg.C("id").Ge(rows/4)).GroupBy(peg.C("day")).Agg(peg.C("id").Sum().Alias("total")).OrderBy(peg.C("day").Asc().NullsLast())); if err!=nil {panic(err)}; defer prepared.Release()
 seg:=a.AllocSegTemp(int(high-low+1)*8); defer seg.Dec(); sums:=seg.AsI64T()
 var outputRows [][]int64
 samples:=map[string][]int64{}
 for round:=0;round<2;round++ {
  modes:=[]string{"current","dense-fused"}; if round==1 {modes=[]string{"dense-fused","current"}}
  for _,mode:=range modes {
   for run:=0;run<39;run++ {
    start:=time.Now()
    if mode=="current" {
     result,err:=prepared.Exec(); if err!=nil {panic(err)}
     elapsed:=time.Since(start).Nanoseconds()
     if run>=8 {samples[mode]=append(samples[mode],elapsed)}
     if run==38 {
      outputRows=nil
      for n:=0;n<result.NumBatches();n++ {batch,_:=result.BatchAt(n); day,_:=batch.Column("day"); sum,_:=batch.Column("total"); for row,v:=range day.Int32s() {outputRows=append(outputRows,[]int64{int64(v),sum.Int64s()[row]})}}
     }
     result.Release()
    } else {
     clear(sums)
     for n:=0;n<table.NBatches();n++ {batch:=table.BatchAt(n); ids,days:=batch.VectorAt(0).I32s(),batch.VectorAt(1).I32s(); for row,id:=range ids {if id>=rows/4 {sums[days[row]-low]+=int64(id)}}}
     if run>=8 {samples[mode]=append(samples[mode],time.Since(start).Nanoseconds())}
    }
   }
  }
 }
 for _,row:=range outputRows {if sums[int32(row[0])-low]!=row[1] {panic(fmt.Sprintf("mismatch: %v",row))}}
 if len(outputRows)!=len(sums) {panic("missing groups")}
 json.NewEncoder(os.Stdout).Encode(map[string]any{"times_ns":samples,"key_min":low,"key_max":high,"groups":len(sums),"matches_current":true,"rows":outputRows,"prototype_scope":"all-valid INT32 inputs, bounded date domain, fused filter and SUM; no general planner/operator semantics"})
}

