import os,json,pathlib,subprocess,statistics
root=pathlib.Path('/tmp/peg-gap-diagnosis')
for workers in (1,4):
 for source in ('parquet','table'):
  reports=[]
  for query in ('','group_day_sum'):
   args=[str(root/'peg'),'-parquet','/tmp/peg-baseline.zZwcQ3/bench.parquet','-rows','1048768','-workers',str(workers),'-source',source,'-warmup','8','-runs','31']
   if query:args+=['-only',query]
   report=json.loads(subprocess.check_output(args,text=True,env={**os.environ,'GOMAXPROCS':str(workers)}))
   reports.append(report)
   for q in report['queries']:print(workers,source,q['name'],round(statistics.median(q['exec_ns'])/1e6,3),'ms',flush=True)
  (root/f'ablation-{source}-w{workers}.json').write_text(json.dumps(reports,indent=2))
